// Unit tests of layer-major evaluation across objects (REQ-LAYER-001; REQ-LAYER-002 ordering,
// REQ-LAYER-005 cache agreement, REQ-CORE-001 determinism): the read view handed to a
// characteristic-defining power or toughness (CR 604.3, 613.4a, 613.5), the source view handed
// to the existence question of an effect generated by another object (CR 613.8a, 611.3, 113.6),
// the universe rule and order independence. Synthetic ids and characteristics only (R5).

use std::cell::RefCell;
use std::collections::{BTreeMap, BTreeSet};

use fineprint_base::ids::{EffectId, ObjectId, PlayerId, Timestamp};
use fineprint_dsl::ability::Layer;
use fineprint_dsl::card::{AbilityAST, ColorBitmask, TextTokenStream, ValueExpressionAST};
use fineprint_dsl::expr::{ObjectSelectorAST, PredicateAST, ReferenceAST, SelectorFilter, WordRef};

use super::*;
use crate::objects::Characteristics;

// ---------------------------------------------------------------------------------------------
// Fixtures
// ---------------------------------------------------------------------------------------------

const P1: PlayerId = PlayerId::new(1);
const P2: PlayerId = PlayerId::new(2);

fn o(n: u64) -> ObjectId {
    ObjectId::new(n)
}

fn e(n: u64) -> EffectId {
    EffectId::new(n)
}

fn ts(n: u64) -> Timestamp {
    Timestamp::new(n)
}

fn set(items: &[&str]) -> BTreeSet<String> {
    items.iter().map(|s| (*s).to_owned()).collect()
}

fn ability(tag: &str) -> AbilityAST {
    test_ability(&format!("test.ability.{tag}"))
}

/// The characteristic-defining expression "the number of creatures its controller controls"
/// as the synthetic environment reads it (a non-literal expression, `{"MEMORY": key}`).
fn count_expr() -> ValueExpressionAST {
    ValueExpressionAST::Memory("test.count_controller_creatures".to_owned())
}

/// A synthetic creature `test.<name>` with literal P/T and the given abilities.
fn creature(name: &str, power: i64, toughness: i64, abilities: Vec<AbilityAST>) -> Characteristics {
    Characteristics {
        names: set(&[&format!("test.{name}")]),
        mana_cost: None,
        color_indicator: None,
        colors: ColorBitmask::BLACK,
        supertypes: BTreeSet::new(),
        card_types: set(&["Creature"]),
        subtypes: set(&["Golem"]),
        rules_text: TextTokenStream::default(),
        abilities,
        power: Some(literal(power)),
        toughness: Some(literal(toughness)),
        loyalty: None,
        defense: None,
        hand_modifier: None,
        life_modifier: None,
    }
}

/// `test.cda_counter`: a creature whose power is [`count_expr`] and toughness 5.
fn cda_creature() -> Characteristics {
    let mut c = creature("cda_counter", 0, 5, Vec::new());
    c.power = Some(count_expr());
    c
}

/// A synthetic artifact `test.<name>` without power and toughness.
fn artifact(name: &str, abilities: Vec<AbilityAST>) -> Characteristics {
    let mut c = creature(name, 0, 0, abilities);
    c.card_types = set(&["Artifact"]);
    c.subtypes = BTreeSet::new();
    c.power = None;
    c.toughness = None;
    c
}

fn filter(pred: Option<PredicateAST>) -> ObjectSelectorAST {
    ObjectSelectorAST::Filter(SelectorFilter {
        zones: None,
        count: None,
        ordering: None,
        predicate: pred.map(Box::new),
    })
}

/// Every object (a filter without predicate, as the synthetic environment reads it).
fn everything() -> Affected {
    Affected::Selector(filter(None))
}

/// The objects with the card type `t`.
fn with_type(t: &str) -> Affected {
    Affected::Selector(filter(Some(PredicateAST::HasCardType {
        value: WordRef::Name(t.to_owned()),
    })))
}

/// The objects without any ability (the synthetic environment reads `HasKeyword "*"` as "has
/// any ability").
fn without_abilities() -> Affected {
    Affected::Selector(filter(Some(PredicateAST::Not(Box::new(
        PredicateAST::HasKeyword {
            keyword: "*".to_owned(),
        },
    )))))
}

fn only(ids: &[ObjectId]) -> Affected {
    Affected::Objects(ids.iter().copied().collect())
}

/// A resolved effect without a source.
fn resolved(layer: Layer, t: u64, affected: Affected, m: LayerModification) -> ContinuousEffect {
    ContinuousEffect {
        source: None,
        controller: P1,
        timestamp: ts(t),
        layer,
        is_cda: false,
        origin: EffectOrigin::Resolved,
        affected,
        modification: m,
    }
}

/// A static effect of `source`'s own ability.
fn stat(
    source: ObjectId,
    layer: Layer,
    t: u64,
    affected: Affected,
    m: LayerModification,
) -> ContinuousEffect {
    ContinuousEffect {
        source: Some(source),
        origin: EffectOrigin::Static { granted_at: None },
        ..resolved(layer, t, affected, m)
    }
}

fn registry(list: &[(u64, ContinuousEffect)]) -> ContinuousEffects {
    let mut r = ContinuousEffects::new();
    for (id, effect) in list {
        r.register(e(*id), effect.clone()).unwrap();
    }
    r
}

fn add_creature_type() -> LayerModification {
    LayerModification::AddTypes {
        supertypes: BTreeSet::new(),
        card_types: set(&["Creature"]),
        subtypes: BTreeSet::new(),
    }
}

fn only_artifact_type() -> LayerModification {
    LayerModification::SetTypes {
        supertypes: None,
        card_types: Some(set(&["Artifact"])),
        subtypes: None,
    }
}

/// One recorded view: `(object, layer, objects, every object's state)`.
type ViewCall = (
    ObjectId,
    Layer,
    Vec<ObjectId>,
    BTreeMap<ObjectId, Evaluated>,
);

/// One recorded call of [`LayerEnvironment::generating_ability_exists`].
type ExistCall = (EffectId, ObjectId, Option<Evaluated>);

/// A synthetic environment. `objects()` is `order` when set (any order, duplicates allowed),
/// else the ids of `bases` ascending. With `view_aware`, a characteristic-defining value is
/// computed from the [`EvaluatedView`]; without it, from the bases (the per-object behaviour
/// before layer-major evaluation, a control). A linked effect (`generators`) exists only when
/// the source view is given and has the linked ability.
#[derive(Default)]
struct XEnv {
    bases: BTreeMap<ObjectId, ObjectBase>,
    order: Option<Vec<ObjectId>>,
    view_aware: bool,
    generators: BTreeMap<EffectId, AbilityAST>,
    /// `(object, with view)` for every characteristic-defining value asked.
    eval_calls: RefCell<Vec<(ObjectId, bool)>>,
    /// The views handed out: `(object, layer, objects, every object's state)`.
    views: RefCell<Vec<ViewCall>>,
    exist_calls: RefCell<Vec<ExistCall>>,
}

impl XEnv {
    fn view_aware() -> XEnv {
        XEnv {
            view_aware: true,
            ..XEnv::default()
        }
    }

    fn with(mut self, id: ObjectId, c: Characteristics, controller: PlayerId) -> XEnv {
        self.bases.insert(
            id,
            ObjectBase {
                characteristics: c,
                controller: Some(controller),
                on_battlefield: true,
            },
        );
        self
    }

    fn generator(mut self, effect: EffectId, ab: AbilityAST) -> XEnv {
        self.generators.insert(effect, ab);
        self
    }

    fn ordered(mut self, order: Vec<ObjectId>) -> XEnv {
        self.order = Some(order);
        self
    }

    fn base_count(&self, object: ObjectId) -> i64 {
        let controller = self.bases.get(&object).and_then(|b| b.controller);
        let n = self
            .bases
            .values()
            .filter(|b| {
                b.controller == controller && b.characteristics.card_types.contains("Creature")
            })
            .count();
        i64::try_from(n).unwrap()
    }
}

fn holds(pred: &PredicateAST, view: &Evaluated) -> bool {
    let c = &view.characteristics;
    match pred {
        PredicateAST::And(all) => all.iter().all(|q| holds(q, view)),
        PredicateAST::Not(q) => !holds(q, view),
        PredicateAST::IsCreature => c.card_types.contains("Creature"),
        PredicateAST::HasCardType {
            value: WordRef::Name(t),
        } => c.card_types.contains(t),
        PredicateAST::HasKeyword { keyword } if keyword == "*" => !c.abilities.is_empty(),
        _ => false,
    }
}

impl LayerEnvironment for XEnv {
    fn objects(&self) -> Vec<ObjectId> {
        self.order
            .clone()
            .unwrap_or_else(|| self.bases.keys().copied().collect())
    }

    fn base(&self, id: ObjectId) -> Option<ObjectBase> {
        self.bases.get(&id).cloned()
    }

    fn matches(&self, selector: &ObjectSelectorAST, ctx: &MatchContext<'_>) -> bool {
        match selector {
            ObjectSelectorAST::Ref(ReferenceAST::SelfRef) => ctx.source == Some(ctx.candidate),
            ObjectSelectorAST::Filter(f) => f
                .predicate
                .as_ref()
                .is_none_or(|q| holds(q, ctx.candidate_view)),
            ObjectSelectorAST::Ref(_) => false,
        }
    }

    fn eval_value(&self, expr: &ValueExpressionAST, object: ObjectId) -> Option<i64> {
        self.eval_calls.borrow_mut().push((object, false));
        // Without the view only the bases are known (the behaviour before #186).
        (expr == &count_expr()).then(|| self.base_count(object))
    }

    fn eval_value_with_view(
        &self,
        expr: &ValueExpressionAST,
        object: ObjectId,
        view: &EvaluatedView<'_>,
    ) -> Option<i64> {
        if !self.view_aware {
            return self.eval_value(expr, object);
        }
        self.eval_calls.borrow_mut().push((object, true));
        let all = view.objects();
        self.views.borrow_mut().push((
            object,
            view.layer(),
            all.clone(),
            all.iter()
                .map(|&y| (y, view.get(y).unwrap().clone()))
                .collect(),
        ));
        if expr != &count_expr() {
            return None;
        }
        // CR 604.3, 613.5: "creatures its controller controls", by the evaluated controller.
        let controller = view.get(object)?.controller;
        let n = all
            .iter()
            .filter_map(|&y| view.get(y))
            .filter(|y| {
                y.controller == controller && y.characteristics.card_types.contains("Creature")
            })
            .count();
        Some(i64::try_from(n).unwrap())
    }

    fn generating_ability_exists(
        &self,
        effect: EffectId,
        source: ObjectId,
        source_view: Option<&Evaluated>,
    ) -> bool {
        self.exist_calls
            .borrow_mut()
            .push((effect, source, source_view.cloned()));
        match self.generators.get(&effect) {
            // CR 613.8a, 611.3, 113.6: judged ONLY from the view; no view, no ability.
            Some(ab) => source_view.is_some_and(|v| v.characteristics.abilities.contains(ab)),
            None => true,
        }
    }
}

fn power(ev: &Evaluated) -> Option<i64> {
    literal_of(ev.characteristics.power.as_ref()?)
}

/// The board of acceptance scenario 1 with the CDA object at `c`: K1, K2 creatures of P1, K3 a
/// creature of P2, N a noncreature artifact of P1 (ids 20-23 and 30).
fn board(c: ObjectId) -> XEnv {
    XEnv::view_aware()
        .with(c, cda_creature(), P1)
        .with(o(20), creature("k1", 1, 1, Vec::new()), P1)
        .with(o(21), creature("k2", 2, 2, Vec::new()), P1)
        .with(o(22), creature("k3", 3, 3, Vec::new()), P2)
        .with(o(30), artifact("n", Vec::new()), P1)
}

/// Asserts `evaluate(id) == evaluate_all()[id] == evaluate_with_order(id).0` for every object
/// (REQ-LAYER-001) and returns the board.
fn all_consistent(r: &ContinuousEffects, env: &XEnv) -> BTreeMap<ObjectId, Evaluated> {
    let all = evaluate_all(r, env).unwrap();
    for (&id, ev) in &all {
        assert_eq!(&evaluate(r, env, id).unwrap(), ev, "{id:?}");
        assert_eq!(&evaluate_with_order(r, env, id).unwrap().0, ev, "{id:?}");
    }
    all
}

// ---------------------------------------------------------------------------------------------
// Acceptance scenario 1 (a): layer-2 control changes
// ---------------------------------------------------------------------------------------------

/// REQ-LAYER-001, CR 604.3, 613.1b, 613.4a, 613.5: C counts the creatures its controller
/// controls. Control (no effect): 3 (C, K1, K2). A layer-2 control change of K1 to P2 lowers it
/// to 2, whether the effect's timestamp is before or after C's; the base-only environment (the
/// behaviour before layer-major evaluation) does not see it.
#[test]
fn req_layer_001_cda_sees_layer_2_control_change_of_another_object() {
    for c in [o(1), o(50)] {
        let env = board(c);
        assert_eq!(power(&evaluate(&registry(&[]), &env, c).unwrap()), Some(3));
        for t in [1, 100] {
            let r = registry(&[(
                1,
                resolved(
                    Layer::L2,
                    t,
                    only(&[o(20)]),
                    LayerModification::SetController(P2),
                ),
            )]);
            let all = all_consistent(&r, &env);
            assert_eq!(power(&all[&c]), Some(2), "{c:?} t{t}");
            assert_eq!(all[&o(20)].controller, Some(P2));
            // Control: the base-only behaviour keeps 3.
            let mut old = board(c);
            old.view_aware = false;
            assert_eq!(
                power(&evaluate(&r, &old, c).unwrap()),
                Some(3),
                "{c:?} t{t}"
            );
        }
    }
}

/// REQ-LAYER-001, CR 604.3, 613.1b, 613.4a, 613.5: a layer-2 control change of C itself to P2
/// changes which player's creatures are counted: P2 controls C and K3, so 2; the count follows
/// C's evaluated controller, not its base controller (base-only control: 3).
#[test]
fn req_layer_001_cda_counts_for_its_evaluated_controller() {
    for c in [o(1), o(50)] {
        let env = board(c);
        for t in [1, 100] {
            let r = registry(&[(
                1,
                resolved(
                    Layer::L2,
                    t,
                    only(&[c]),
                    LayerModification::SetController(P2),
                ),
            )]);
            let all = all_consistent(&r, &env);
            assert_eq!(all[&c].controller, Some(P2));
            assert_eq!(power(&all[&c]), Some(2), "{c:?} t{t}");
            // Also moving K1 and K2 to P2: P2 controls C, K1, K2, K3.
            let r = registry(&[
                (
                    1,
                    resolved(
                        Layer::L2,
                        t,
                        only(&[c]),
                        LayerModification::SetController(P2),
                    ),
                ),
                (
                    2,
                    resolved(
                        Layer::L2,
                        50,
                        only(&[o(20), o(21)]),
                        LayerModification::SetController(P2),
                    ),
                ),
            ]);
            assert_eq!(power(&all_consistent(&r, &env)[&c]), Some(4), "{c:?} t{t}");
            let mut old = board(c);
            old.view_aware = false;
            assert_eq!(power(&evaluate(&r, &old, c).unwrap()), Some(3));
        }
    }
}

// ---------------------------------------------------------------------------------------------
// Acceptance scenario 1 (b): layer-4 type changes
// ---------------------------------------------------------------------------------------------

/// REQ-LAYER-001, CR 604.3, 613.1d, 613.4a, 613.5: a layer-4 effect that makes the noncreature
/// N (controlled by P1) a creature raises C's count to 4, by a locked set or by a selector, with
/// the effect's timestamp before or after C's (control without it: 3; base-only: 3).
#[test]
fn req_layer_001_cda_sees_layer_4_type_change_of_another_object() {
    for c in [o(1), o(50)] {
        let env = board(c);
        for t in [1, 100] {
            for affected in [only(&[o(30)]), with_type("Artifact")] {
                let r = registry(&[(1, resolved(Layer::L4, t, affected, add_creature_type()))]);
                let all = all_consistent(&r, &env);
                assert!(all[&o(30)].characteristics.card_types.contains("Creature"));
                assert_eq!(power(&all[&c]), Some(4), "{c:?} t{t}");
                let mut old = board(c);
                old.view_aware = false;
                assert_eq!(power(&evaluate(&r, &old, c).unwrap()), Some(3));
            }
        }
    }
}

/// REQ-LAYER-001, CR 604.3, 613.1d, 613.4a, 613.5: a layer-4 `SetTypes` that removes Creature
/// from K2 lowers C's count to 2 (before or after C's timestamp); a static effect of N doing the
/// same to K1 and K2 (a locked set) lowers it to 1.
#[test]
fn req_layer_001_cda_sees_layer_4_creature_removal() {
    for c in [o(1), o(50)] {
        let env = board(c);
        for t in [1, 100] {
            let r = registry(&[(
                1,
                resolved(Layer::L4, t, only(&[o(21)]), only_artifact_type()),
            )]);
            assert_eq!(power(&all_consistent(&r, &env)[&c]), Some(2), "{c:?} t{t}");
            let r = registry(&[(
                1,
                stat(
                    o(30),
                    Layer::L4,
                    t,
                    only(&[o(20), o(21)]),
                    only_artifact_type(),
                ),
            )]);
            assert_eq!(power(&all_consistent(&r, &env)[&c]), Some(1), "{c:?} t{t}");
        }
    }
}

/// REQ-LAYER-001, CR 613.1b, 613.1d, 613.4a, 613.5: layers 2 and 4 together: K3 moves to P1
/// (layer 2) and N becomes a creature (layer 4): 5.
#[test]
fn req_layer_001_cda_sees_layers_2_and_4_together() {
    let c = o(1);
    let env = board(c);
    let r = registry(&[
        (
            1,
            resolved(
                Layer::L2,
                9,
                only(&[o(22)]),
                LayerModification::SetController(P1),
            ),
        ),
        (
            2,
            resolved(Layer::L4, 3, only(&[o(30)]), add_creature_type()),
        ),
    ]);
    assert_eq!(power(&all_consistent(&r, &env)[&c]), Some(5));
}

// ---------------------------------------------------------------------------------------------
// The view
// ---------------------------------------------------------------------------------------------

/// REQ-LAYER-001, CR 613.4a, 613.5, 613.1b-f: the view handed to the CDA is at layer 7a, lists
/// every object of the universe ascending, and holds each object after layers 1a-6 (controller
/// after layer 2, types after 4, colors after 5, abilities after 6) with its power and
/// toughness as after layer 6 (a layer-7c change is not in it); two CDA objects get the same
/// snapshot whatever their ids.
#[test]
fn req_layer_001_view_contents_at_layer_7a() {
    let env = board(o(1)).with(o(60), cda_creature(), P2);
    let r = registry(&[
        (
            1,
            resolved(
                Layer::L2,
                5,
                only(&[o(20)]),
                LayerModification::SetController(P2),
            ),
        ),
        (
            2,
            resolved(Layer::L4, 5, only(&[o(30)]), add_creature_type()),
        ),
        (
            3,
            resolved(
                Layer::L5,
                5,
                only(&[o(21)]),
                LayerModification::SetColors(ColorBitmask::WHITE),
            ),
        ),
        (
            4,
            resolved(
                Layer::L6,
                5,
                only(&[o(22)]),
                LayerModification::AddAbility(ability("granted")),
            ),
        ),
        (
            5,
            resolved(
                Layer::L7c,
                5,
                only(&[o(21)]),
                LayerModification::ModifyPt {
                    power: 7,
                    toughness: 7,
                },
            ),
        ),
    ]);
    let all = evaluate_all(&r, &env).unwrap();
    let views = env.views.borrow();
    assert_eq!(views.len(), 2, "one view per CDA object");
    let ids = vec![o(1), o(20), o(21), o(22), o(30), o(60)];
    for (object, layer, listed, states) in views.iter() {
        assert_eq!(*layer, Layer::L7a);
        assert_eq!(listed, &ids, "{object:?}");
        assert_eq!(states[&o(20)].controller, Some(P2));
        assert!(
            states[&o(30)]
                .characteristics
                .card_types
                .contains("Creature")
        );
        assert_eq!(states[&o(21)].characteristics.colors, ColorBitmask::WHITE);
        assert!(
            states[&o(22)]
                .characteristics
                .abilities
                .contains(&ability("granted"))
        );
        // After layer 6: K2's literal 2/2, not the layer-7c 9/9; the CDA objects' own
        // expressions are not yet resolved.
        assert_eq!(power(&states[&o(21)]), Some(2));
        assert_eq!(states[&o(1)].characteristics.power, Some(count_expr()));
    }
    assert_eq!(views[0].3, views[1].3, "same snapshot for every object");
    assert_eq!(power(&all[&o(21)]), Some(9));
    // P1: C(1), K2, N; P2: K1, K3, C(60).
    assert_eq!(power(&all[&o(1)]), Some(3));
    assert_eq!(power(&all[&o(60)]), Some(3));
}

/// REQ-LAYER-001, CR 208.3, 604.3, 613.4a: a literal power and toughness never reaches the
/// environment (neither `eval_value` nor `eval_value_with_view`), nor does an object without
/// power and toughness; a non-literal value is asked once, with the view, and `eval_value` is
/// not called by a view-aware environment.
#[test]
fn req_layer_001_literal_pt_takes_the_direct_path() {
    let env = XEnv::view_aware()
        .with(o(1), creature("plain", 2, 2, Vec::new()), P1)
        .with(o(2), artifact("n", Vec::new()), P1);
    let all = evaluate_all(&registry(&[]), &env).unwrap();
    assert_eq!(power(&all[&o(1)]), Some(2));
    assert!(env.eval_calls.borrow().is_empty());
    assert!(env.views.borrow().is_empty());
    let mut old = XEnv::default().with(o(1), creature("plain", 2, 2, Vec::new()), P1);
    old.view_aware = false;
    evaluate(&registry(&[]), &old, o(1)).unwrap();
    assert!(old.eval_calls.borrow().is_empty());
    // Control: the CDA object is asked exactly once, with the view (power only; toughness 5 is
    // literal).
    let env = board(o(1));
    evaluate(&registry(&[]), &env, o(1)).unwrap();
    assert_eq!(*env.eval_calls.borrow(), vec![(o(1), true)]);
}

/// REQ-LAYER-001, CR 604.3: the default `eval_value_with_view` calls `eval_value` without the
/// view, so an environment that overrides only `eval_value` behaves as before.
#[test]
fn req_layer_001_default_eval_value_with_view_calls_eval_value() {
    struct Old;
    impl LayerEnvironment for Old {
        fn objects(&self) -> Vec<ObjectId> {
            vec![o(1)]
        }
        fn base(&self, id: ObjectId) -> Option<ObjectBase> {
            (id == o(1)).then(|| ObjectBase {
                characteristics: cda_creature(),
                controller: Some(P1),
                on_battlefield: true,
            })
        }
        fn matches(&self, _: &ObjectSelectorAST, _: &MatchContext<'_>) -> bool {
            false
        }
        fn eval_value(&self, _: &ValueExpressionAST, _: ObjectId) -> Option<i64> {
            Some(11)
        }
    }
    assert_eq!(
        power(&evaluate(&registry(&[]), &Old, o(1)).unwrap()),
        Some(11)
    );
    // The trait's own default for an unknown expression: 0 (CR 208.5).
    struct Bare;
    impl LayerEnvironment for Bare {
        fn objects(&self) -> Vec<ObjectId> {
            vec![o(1)]
        }
        fn base(&self, id: ObjectId) -> Option<ObjectBase> {
            Old.base(id)
        }
        fn matches(&self, _: &ObjectSelectorAST, _: &MatchContext<'_>) -> bool {
            false
        }
    }
    assert_eq!(
        power(&evaluate(&registry(&[]), &Bare, o(1)).unwrap()),
        Some(0)
    );
}

// ---------------------------------------------------------------------------------------------
// Universe and errors
// ---------------------------------------------------------------------------------------------

/// REQ-LAYER-001: an id that is not in `env.objects()` but has a base evaluates (and joins its
/// own universe); an unknown id is `UnknownObject`; `evaluate_all` with objects lacking a base
/// fails on the first by ascending id whatever the order of `env.objects()`, while `evaluate` of
/// a known object leaves those objects out of the view.
#[test]
fn req_layer_001_universe_rule() {
    let r = registry(&[]);
    // H (a P1 creature) is not listed.
    let env = board(o(1))
        .with(o(40), creature("h", 1, 1, Vec::new()), P1)
        .ordered(vec![o(1), o(20), o(21), o(22), o(30)]);
    assert_eq!(power(&evaluate(&r, &env, o(1)).unwrap()), Some(3));
    assert_eq!(power(&evaluate(&r, &env, o(40)).unwrap()), Some(1));
    assert!(!evaluate_all(&r, &env).unwrap().contains_key(&o(40)));
    // H is in its own universe: the view of a CDA H counts itself.
    let env =
        board(o(1))
            .with(o(40), cda_creature(), P1)
            .ordered(vec![o(1), o(20), o(21), o(22), o(30)]);
    assert_eq!(power(&evaluate(&r, &env, o(40)).unwrap()), Some(4));
    assert_eq!(power(&evaluate(&r, &env, o(1)).unwrap()), Some(3));
    // Unknown.
    assert_eq!(
        evaluate(&r, &env, o(99)),
        Err(LayerError::UnknownObject(o(99)))
    );
    assert_eq!(
        copiable_values(&r, &env, o(99)).map(|_| ()),
        Err(LayerError::UnknownObject(o(99)))
    );
    // Listed objects without a base.
    let env = board(o(1)).ordered(vec![o(98), o(1), o(97), o(20), o(21), o(22), o(30)]);
    assert_eq!(
        evaluate_all(&r, &env),
        Err(LayerError::UnknownObject(o(97)))
    );
    assert_eq!(power(&evaluate(&r, &env, o(1)).unwrap()), Some(3));
    let mut cache = LayerCache::new();
    assert!(cache.evaluate_all(&r, &env).is_err());
}

// ---------------------------------------------------------------------------------------------
// Order independence (REQ-CORE-001)
// ---------------------------------------------------------------------------------------------

fn permutations(ids: &[ObjectId]) -> Vec<Vec<ObjectId>> {
    let mut reversed = ids.to_vec();
    reversed.reverse();
    let mut duplicated = ids.to_vec();
    duplicated.extend(reversed.iter().copied());
    let mut rotated = ids.to_vec();
    rotated.rotate_left(ids.len() / 2);
    vec![ids.to_vec(), reversed, duplicated, rotated]
}

/// REQ-LAYER-001, REQ-CORE-001, CR 613.5, 613.7: the board is the same for every order and
/// duplication of `env.objects()` and every registration order of the effects, with the CDA
/// object's id below and above the objects it counts; the cache agrees (REQ-LAYER-005).
#[test]
fn req_layer_001_results_independent_of_object_and_registration_order() {
    for c in [o(1), o(50)] {
        let list = vec![
            (
                1,
                resolved(
                    Layer::L2,
                    7,
                    only(&[o(20)]),
                    LayerModification::SetController(P2),
                ),
            ),
            (
                2,
                resolved(Layer::L4, 3, with_type("Artifact"), add_creature_type()),
            ),
            (
                3,
                stat(
                    o(22),
                    Layer::L2,
                    1,
                    only(&[o(22)]),
                    LayerModification::SetController(P1),
                ),
            ),
        ];
        let mut reversed = list.clone();
        reversed.reverse();
        let base = evaluate_all(&registry(&list), &board(c)).unwrap();
        // P1: C, K2, K3, N.
        assert_eq!(power(&base[&c]), Some(4));
        let ids: Vec<ObjectId> = base.keys().copied().collect();
        for order in permutations(&ids) {
            for l in [&list, &reversed] {
                let env = board(c).ordered(order.clone());
                let r = registry(l);
                assert_eq!(all_consistent(&r, &env), base, "{order:?}");
                let mut cache = LayerCache::new();
                assert_eq!(cache.evaluate_all(&r, &env).unwrap(), base);
                for &id in &ids {
                    assert_eq!(cache.evaluate(&r, &env, id).unwrap(), base[&id]);
                }
            }
        }
    }
}

// ---------------------------------------------------------------------------------------------
// The source view of the existence question (CR 613.8a, 611.3, 113.6)
// ---------------------------------------------------------------------------------------------

/// REQ-LAYER-001, REQ-LAYER-002, CR 613.8a, 611.3, 113.6, 613.1b: a static layer-4 effect E of
/// K1 adds a subtype to every creature. When another object is evaluated, the existence of E is
/// asked with `Some(K1's state)`: K1 after layer 2 (controller P2), after the other layer-4
/// effects (subtype `Wall` from a resolved effect), without E itself (no `Marked`) and without
/// later layers (the layer-5 color change is not in it). When K1 itself is evaluated, with its
/// state so far.
#[test]
fn req_layer_001_foreign_source_view_contents() {
    let env = board(o(1)).generator(e(1), ability("e_gen"));
    let mut env = env;
    env.bases
        .get_mut(&o(20))
        .unwrap()
        .characteristics
        .abilities
        .push(ability("e_gen"));
    let marked = LayerModification::AddTypes {
        supertypes: BTreeSet::new(),
        card_types: BTreeSet::new(),
        subtypes: set(&["Marked"]),
    };
    let wall = LayerModification::AddTypes {
        supertypes: BTreeSet::new(),
        card_types: BTreeSet::new(),
        subtypes: set(&["Wall"]),
    };
    let r = registry(&[
        (1, stat(o(20), Layer::L4, 5, with_type("Creature"), marked)),
        (
            2,
            resolved(
                Layer::L2,
                9,
                only(&[o(20)]),
                LayerModification::SetController(P2),
            ),
        ),
        (3, resolved(Layer::L4, 9, only(&[o(20)]), wall)),
        (
            4,
            resolved(
                Layer::L5,
                1,
                only(&[o(20)]),
                LayerModification::SetColors(ColorBitmask::WHITE),
            ),
        ),
    ]);
    let all = all_consistent(&r, &env);
    // E exists: every creature is Marked.
    for id in [o(1), o(20), o(21), o(22)] {
        assert!(
            all[&id].characteristics.subtypes.contains("Marked"),
            "{id:?}"
        );
    }
    env.exist_calls.borrow_mut().clear();
    evaluate(&r, &env, o(21)).unwrap();
    let calls = env.exist_calls.borrow();
    assert!(!calls.is_empty());
    // The board pass also evaluates K1 itself (asked with its state so far); every call has a
    // view, and the other objects' calls carry the foreign view described above.
    let foreign = |v: &Evaluated| {
        v.controller == Some(P2)
            && v.characteristics.subtypes.contains("Wall")
            && !v.characteristics.subtypes.contains("Marked")
            && v.characteristics.colors == ColorBitmask::BLACK
    };
    for (effect, source, view) in calls.iter() {
        assert_eq!((*effect, *source), (e(1), o(20)));
        let view = view.as_ref().expect("a source in the universe gets a view");
        assert_eq!(view.controller, Some(P2), "after layer 2");
        assert!(!view.characteristics.subtypes.contains("Marked"));
        assert_eq!(
            view.characteristics.colors,
            ColorBitmask::BLACK,
            "before layer 5"
        );
    }
    assert!(calls.iter().any(|c| c.2.as_ref().is_some_and(foreign)));
    // Without K1's own evaluation in the count: the calls for the other creatures all see the
    // foreign view (K1 through the end of layer 4 without E).
    let n_foreign = calls
        .iter()
        .filter(|c| c.2.as_ref().is_some_and(foreign))
        .count();
    assert!(n_foreign >= 3, "{n_foreign}");
    drop(calls);
    // A source outside the universe gets no view.
    let r = registry(&[(
        1,
        stat(
            o(77),
            Layer::L4,
            5,
            with_type("Creature"),
            add_creature_type(),
        ),
    )]);
    env.exist_calls.borrow_mut().clear();
    evaluate(&r, &env, o(21)).unwrap();
    assert!(env.exist_calls.borrow().iter().all(|c| c.2.is_none()));
    // Resolved effects and static effects without a source are never asked.
    let r = registry(&[
        (
            1,
            resolved(Layer::L4, 5, with_type("Creature"), add_creature_type()),
        ),
        (
            2,
            ContinuousEffect {
                origin: EffectOrigin::Static { granted_at: None },
                ..resolved(Layer::L4, 5, with_type("Creature"), add_creature_type())
            },
        ),
    ]);
    env.exist_calls.borrow_mut().clear();
    evaluate_all(&r, &env).unwrap();
    assert!(env.exist_calls.borrow().is_empty());
}

/// REQ-LAYER-001, REQ-LAYER-002, CR 613.8a, 611.3, 113.6: a static layer-4 effect E of N exists
/// while N, as evaluated through the end of layer 4, has the generating ability. Control: E
/// exists and C counts N. A layer-1a copy that replaces N's characteristics (an earlier layer)
/// removes the ability, so E applies to no object. A removal in layer 6 (a later layer than E's)
/// is not part of the source view (the brief's R-4 contract: through the end of the effect's own
/// layer), so E still applied in layer 4.
#[test]
fn req_layer_001_foreign_source_loses_ability_in_earlier_layer() {
    let gen_ab = ability("s_gen");
    let mut env = board(o(1)).generator(e(1), gen_ab.clone());
    env.bases
        .get_mut(&o(30))
        .unwrap()
        .characteristics
        .abilities
        .push(gen_ab.clone());
    // E: N's static layer-4 effect making every artifact a creature.
    let e_eff = stat(
        o(30),
        Layer::L4,
        5,
        with_type("Artifact"),
        add_creature_type(),
    );
    // Control: E exists, N is a creature and C counts it.
    let r = registry(&[(1, e_eff.clone())]);
    let all = all_consistent(&r, &env);
    assert!(all[&o(30)].characteristics.card_types.contains("Creature"));
    assert_eq!(power(&all[&o(1)]), Some(4));
    // A layer-1a copy turns N into an artifact without the ability: E no longer exists.
    let copy = LayerModification::CopyValues(Box::new(artifact("n_copy", Vec::new())));
    let r = registry(&[
        (1, e_eff.clone()),
        (2, resolved(Layer::L1a, 9, only(&[o(30)]), copy)),
    ]);
    let all = all_consistent(&r, &env);
    assert!(!all[&o(30)].characteristics.card_types.contains("Creature"));
    assert_eq!(power(&all[&o(1)]), Some(3));
    // A removal in a LATER layer (6) is not in the source view (brief R-4: through the end of
    // the effect's own layer), so E still applied in layer 4.
    let r = registry(&[
        (1, e_eff),
        (
            2,
            resolved(
                Layer::L6,
                1,
                only(&[o(30)]),
                LayerModification::RemoveAllAbilities,
            ),
        ),
    ]);
    let all = all_consistent(&r, &env);
    assert!(all[&o(30)].characteristics.card_types.contains("Creature"));
    assert!(all[&o(30)].characteristics.abilities.is_empty());
}

/// The #183 scenario on an environment that answers existence ONLY from the source view:
/// A (source sA) removes all abilities from every object in layer 6, B (source sB) grants a
/// marker to objects without abilities in layer 6. Returns the board.
fn same_layer_scene(
    (t_a, t_b): (u64, u64),
    register_b_first: bool,
    with_a: bool,
    order: Option<Vec<ObjectId>>,
) -> BTreeMap<ObjectId, Evaluated> {
    let (sa, sb, t) = (o(3), o(4), o(5));
    let mut env = XEnv::view_aware()
        .with(sa, artifact("sa", vec![ability("a_gen")]), P1)
        .with(sb, artifact("sb", vec![ability("b_gen")]), P1)
        .with(t, creature("t", 1, 1, Vec::new()), P2)
        .generator(e(1), ability("a_gen"))
        .generator(e(2), ability("b_gen"));
    env.order = order;
    let a = (
        1,
        stat(
            sa,
            Layer::L6,
            t_a,
            everything(),
            LayerModification::RemoveAllAbilities,
        ),
    );
    let b = (
        2,
        stat(
            sb,
            Layer::L6,
            t_b,
            without_abilities(),
            LayerModification::AddAbility(ability("marker")),
        ),
    );
    let list = match (with_a, register_b_first) {
        (false, _) => vec![b],
        (true, false) => vec![a, b],
        (true, true) => vec![b, a],
    };
    all_consistent(&registry(&list), &env)
}

/// REQ-LAYER-001, REQ-LAYER-002, CR 613.8a, 611.3, 113.6 (the #183 same-layer trap): with an
/// environment that judges existence only from the source view, no object gets the marker, in
/// both timestamp orders, both registration orders and any object order: B's source loses B's
/// generating ability to A in the SAME layer, which a start-of-layer snapshot would miss.
/// Control: without A, B exists through the foreign view (it would not with `None`) and the
/// object without abilities gets the marker.
#[test]
fn req_layer_001_same_layer_removal_on_foreign_source() {
    let marker = ability("marker");
    for (t_a, t_b) in [(1, 2), (2, 1)] {
        for register_b_first in [false, true] {
            for order in [None, Some(vec![o(5), o(4), o(3), o(5)])] {
                let all = same_layer_scene((t_a, t_b), register_b_first, true, order);
                for (id, ev) in &all {
                    assert!(
                        !ev.characteristics.abilities.contains(&marker),
                        "{id:?} t{t_a}/{t_b} b-first {register_b_first}"
                    );
                    assert!(ev.characteristics.abilities.is_empty());
                }
            }
        }
    }
    let all = same_layer_scene((1, 2), false, false, None);
    assert_eq!(all[&o(5)].characteristics.abilities, vec![marker.clone()]);
    assert!(!all[&o(3)].characteristics.abilities.contains(&marker));
}

/// REQ-LAYER-001, REQ-OBJ-002, CR 613.2a, 613.2c, 613.8a: `copiable_values` is the layer-1
/// prefix of the board: a static layer-1a copy effect generated by another object exists through
/// that object's view in both.
#[test]
fn req_layer_001_copiable_values_match_board_prefix() {
    let mut env = board(o(1)).generator(e(1), ability("copy_gen"));
    env.bases
        .get_mut(&o(30))
        .unwrap()
        .characteristics
        .abilities
        .push(ability("copy_gen"));
    let model = creature("model", 4, 4, Vec::new());
    let r = registry(&[(
        1,
        stat(
            o(30),
            Layer::L1a,
            3,
            only(&[o(21)]),
            LayerModification::CopyValues(Box::new(model.clone())),
        ),
    )]);
    let values = copiable_values(&r, &env, o(21)).unwrap();
    assert_eq!(&values.characteristics, &model);
    assert_eq!(evaluate(&r, &env, o(21)).unwrap().characteristics, model);
    // Without the generating ability on N the copy does not exist in either.
    env.bases
        .get_mut(&o(30))
        .unwrap()
        .characteristics
        .abilities
        .clear();
    let values = copiable_values(&r, &env, o(21)).unwrap();
    assert_eq!(&values.characteristics, &creature("k2", 2, 2, Vec::new()));
}

// ---------------------------------------------------------------------------------------------
// Property (REQ-LAYER-001 R-2, R-7; REQ-CORE-001)
// ---------------------------------------------------------------------------------------------

/// A small deterministic linear congruential generator (no rand crate, no clock).
struct Lcg(u64);

impl Lcg {
    fn below(&mut self, n: u64) -> u64 {
        self.0 = self
            .0
            .wrapping_mul(6_364_136_223_846_793_005)
            .wrapping_add(1_442_695_040_888_963_407);
        (self.0 >> 33) % n
    }
}

/// REQ-LAYER-001, REQ-LAYER-002, REQ-LAYER-005, REQ-CORE-001, CR 604.3, 613.1b, 613.1d, 613.5,
/// 613.8a: over 150 random small boards (CDA counters, creatures and artifacts of two players,
/// static and resolved effects of layers 2, 4 and 6 from random sources with generating
/// abilities): `evaluate(id) == evaluate_with_order(id).0 == evaluate_all()[id] ==` the cache's,
/// the order record names the object, and the board is identical for reversed, duplicated and
/// rotated `env.objects()` and reversed registration order.
#[test]
fn req_layer_001_property_board_is_order_independent() {
    let mut rng = Lcg(0x0186_0146);
    for seed in 0..150 {
        let n = 3 + rng.below(4);
        let mut ids: Vec<ObjectId> = Vec::new();
        while ids.len() < usize::try_from(n).unwrap() {
            let id = o(1 + rng.below(20));
            if !ids.contains(&id) {
                ids.push(id);
            }
        }
        let mut env = XEnv::view_aware();
        for (i, &id) in ids.iter().enumerate() {
            let controller = if rng.below(2) == 0 { P1 } else { P2 };
            let abilities = vec![ability(&format!("gen{i}"))];
            let c = match rng.below(3) {
                0 => cda_creature(),
                1 => creature("k", 1, 1, abilities.clone()),
                _ => artifact("n", abilities.clone()),
            };
            let mut c = c;
            c.abilities = abilities;
            env = env.with(id, c, controller);
        }
        let mut list = Vec::new();
        for k in 0..(2 + rng.below(5)) {
            let layer = [Layer::L2, Layer::L4, Layer::L6][usize::try_from(rng.below(3)).unwrap()];
            let target = ids[usize::try_from(rng.below(n)).unwrap()];
            let affected = match rng.below(3) {
                0 => only(&[target]),
                1 => with_type("Artifact"),
                _ => everything(),
            };
            let m = match layer {
                Layer::L2 => {
                    LayerModification::SetController(if rng.below(2) == 0 { P1 } else { P2 })
                }
                Layer::L4 => {
                    if rng.below(2) == 0 {
                        add_creature_type()
                    } else {
                        only_artifact_type()
                    }
                }
                _ => {
                    if rng.below(2) == 0 {
                        LayerModification::RemoveAllAbilities
                    } else {
                        LayerModification::AddAbility(ability("marker"))
                    }
                }
            };
            let t = rng.below(6);
            let effect = if rng.below(3) == 0 {
                resolved(layer, t, affected, m)
            } else {
                let si = usize::try_from(rng.below(n)).unwrap();
                env.generators
                    .insert(e(k + 1), ability(&format!("gen{si}")));
                stat(ids[si], layer, t, affected, m)
            };
            list.push((k + 1, effect));
        }
        let r = registry(&list);
        let base = all_consistent(&r, &env);
        let mut cache = LayerCache::new();
        assert_eq!(cache.evaluate_all(&r, &env).unwrap(), base, "seed {seed}");
        for &id in base.keys() {
            let (ev, rec) = evaluate_with_order(&r, &env, id).unwrap();
            assert_eq!(rec.object, id);
            assert_eq!(cache.evaluate(&r, &env, id).unwrap(), ev, "seed {seed}");
        }
        let mut reversed = list.clone();
        reversed.reverse();
        let sorted: Vec<ObjectId> = base.keys().copied().collect();
        for order in permutations(&sorted) {
            for l in [&list, &reversed] {
                let mut env2 = XEnv::view_aware();
                env2.bases = env.bases.clone();
                env2.generators = env.generators.clone();
                env2.order = Some(order.clone());
                assert_eq!(
                    evaluate_all(&registry(l), &env2).unwrap(),
                    base,
                    "seed {seed} {order:?}"
                );
            }
        }
    }
}

/// REQ-LAYER-001, CR 613.5: the board pass's environment adapters forward every method except
/// the existence question unchanged to the caller's environment.
#[test]
fn req_layer_001_board_adapters_forward_the_environment() {
    let env = board(o(1));
    let view = evaluate(&registry(&[]), &env, o(20)).unwrap();
    let answers = super::board::forwarded_answers(
        &env,
        &registry(&[]),
        o(1),
        "+1/+1",
        &count_expr(),
        &filter(Some(PredicateAST::IsCreature)),
        &view,
    );
    assert_eq!(answers.len(), 3);
    assert_eq!(answers[0], answers[1]);
    assert_eq!(answers[0], answers[2]);
}

/// A synthetic neutral ability (a STATIC ability with one RULE `SKIP` effect) with ability id
/// `id` (R5; #232: replaces the former string placeholder abilities).
fn test_ability(id: &str) -> AbilityAST {
    serde_json::from_value(serde_json::json!({
        "abilityId": id,
        "kind": "STATIC",
        "effects": [{"type": "RULE", "kind": "SKIP"}],
    }))
    .expect("valid synthetic ability")
}
